"""Word-search puzzle generator with an independent solving verifier."""

import argparse
import random
import string

# The 8 directions, keyed by compass-style names.
DIRS = {
    "E": (0, 1),
    "W": (0, -1),
    "S": (1, 0),
    "N": (-1, 0),
    "SE": (1, 1),
    "NW": (-1, -1),
    "SW": (1, -1),
    "NE": (-1, 1),
}

MAX_ATTEMPTS = 500


class PlacementError(Exception):
    """Raised when a word cannot be placed in the grid."""


def _fits_and_agrees(grid, word, row, col, dr, dc):
    """Return True if `word` can be placed at (row, col) along (dr, dc),
    allowing overlaps only where existing letters match."""
    size = len(grid)
    end_r = row + dr * (len(word) - 1)
    end_c = col + dc * (len(word) - 1)
    if not (0 <= end_r < size and 0 <= end_c < size):
        return False
    for i, ch in enumerate(word):
        r = row + dr * i
        c = col + dc * i
        cell = grid[r][c]
        if cell is not None and cell != ch:
            return False
    return True


def _place_word(rng, grid, word):
    """Try up to MAX_ATTEMPTS seeded attempts to place `word`.
    Returns (row, col, direction_name) or raises PlacementError."""
    size = len(grid)
    if len(word) > size:
        raise PlacementError(
            f"word {word!r} (length {len(word)}) does not fit in a {size}x{size} grid"
        )
    dir_names = list(DIRS)
    for _ in range(MAX_ATTEMPTS):
        row = rng.randrange(size)
        col = rng.randrange(size)
        dname = rng.choice(dir_names)
        dr, dc = DIRS[dname]
        if _fits_and_agrees(grid, word, row, col, dr, dc):
            for i, ch in enumerate(word):
                r = row + dr * i
                c = col + dc * i
                grid[r][c] = ch
            return (row, col, dname)
    raise PlacementError(
        f"could not place word {word!r} after {MAX_ATTEMPTS} attempts"
    )


def _count_occurrences(grid, word):
    """Count how many times `word` appears anywhere in the grid."""
    size = len(grid)
    count = 0
    for row in range(size):
        for col in range(size):
            for dr, dc in DIRS.values():
                end_r = row + dr * (len(word) - 1)
                end_c = col + dc * (len(word) - 1)
                if not (0 <= end_r < size and 0 <= end_c < size):
                    continue
                if all(grid[row + dr * i][col + dc * i] == ch
                       for i, ch in enumerate(word)):
                    count += 1
    return count


def _fill_blanks(rng, grid, words, placements):
    """Fill empty cells with seeded random letters. Retry the fill until
    no word accidentally appears somewhere other than its recorded spot,
    so solve() unambiguously recovers the recorded placements."""
    size = len(grid)
    while True:
        for r in range(size):
            for c in range(size):
                if grid[r][c] is None:
                    grid[r][c] = rng.choice(string.ascii_uppercase)
        ok = True
        for word in words:
            if _count_occurrences(grid, word) != 1:
                ok = False
                break
        if ok:
            return
        # Wipe only the filler cells and refill with fresh rng draws.
        placed_cells = set()
        for word, (row, col, dname) in placements.items():
            dr, dc = DIRS[dname]
            for i in range(len(word)):
                placed_cells.add((row + dr * i, col + dc * i))
        for r in range(size):
            for c in range(size):
                if (r, c) not in placed_cells:
                    grid[r][c] = None


def generate(words, size, seed):
    """Generate a size x size word-search puzzle.

    Returns (grid, placements) where grid is a list of strings and
    placements maps each word -> (row, col, direction_name).
    Raises PlacementError if any word cannot be placed.
    """
    words = [w.upper() for w in words]
    rng = random.Random(seed)
    grid = [[None] * size for _ in range(size)]
    placements = {}
    for word in words:
        placements[word] = _place_word(rng, grid, word)
    _fill_blanks(rng, grid, words, placements)
    return ["".join(row) for row in grid], placements


def solve(grid, words):
    """Independently locate each word in the grid.

    Returns a dict mapping word -> ((row, col), direction_name).
    Raises ValueError if a word cannot be found.
    """
    size = len(grid)
    found = {}
    for word in words:
        word = word.upper()
        result = None
        for row in range(size):
            for col in range(size):
                for dname, (dr, dc) in DIRS.items():
                    end_r = row + dr * (len(word) - 1)
                    end_c = col + dc * (len(word) - 1)
                    if not (0 <= end_r < size and 0 <= end_c < size):
                        continue
                    if all(grid[row + dr * i][col + dc * i] == ch
                           for i, ch in enumerate(word)):
                        result = ((row, col), dname)
                        break
                if result:
                    break
            if result:
                break
        if result is None:
            raise ValueError(f"word {word!r} not found in grid")
        found[word] = result
    return found


def render(grid):
    """Render the grid as a spaced-out block of text."""
    return "\n".join(" ".join(row) for row in grid)


def main(argv=None):
    parser = argparse.ArgumentParser(
        description="Generate a word-search puzzle and print it with an answer key."
    )
    parser.add_argument("words", nargs="+", help="words to hide in the puzzle")
    parser.add_argument("--size", type=int, default=15, help="grid size (default 15)")
    parser.add_argument("--seed", type=int, default=None, help="random seed")
    args = parser.parse_args(argv)

    seed = args.seed if args.seed is not None else random.randrange(10**6)
    try:
        grid, placements = generate(args.words, args.size, seed)
    except PlacementError as exc:
        parser.error(str(exc))

    print(f"Word search (size={args.size}, seed={seed})\n")
    print(render(grid))
    print("\nAnswer key:")
    for word in sorted(placements):
        row, col, dname = placements[word]
        print(f"  {word:<15} start=({row}, {col})  direction={dname}")


if __name__ == "__main__":
    main()

